var embeddedFontBase64Regular = LIBERATION_SANS_REGULAR_BASE64 || "";
try {
  if (!embeddedFontBase64Bold || !embeddedFontBase64Regular) {
    let currentDir = process.cwd();
    try {
      currentDir = typeof __dirname !== "undefined" ? __dirname : path2.dirname(fileURLToPath(import.meta.url));
    } catch {
      currentDir = process.cwd();
    }
    const boldCandidates = [
      path2.join(currentDir, "assets/fonts/LiberationSans-Bold.ttf"),
      path2.join(process.cwd(), "src/assets/fonts/LiberationSans-Bold.ttf"),
      "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"
    ];
    for (const p of boldCandidates) {
      if (fs2.existsSync(p)) {
        embeddedFontBase64Bold = fs2.readFileSync(p).toString("base64");
        break;
      }
    }
    const regularCandidates = [
      path2.join(currentDir, "assets/fonts/LiberationSans-Regular.ttf"),
      path2.join(process.cwd(), "src/assets/fonts/LiberationSans-Regular.ttf"),
      "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf"
    ];
    for (const p of regularCandidates) {
      if (fs2.existsSync(p)) {
        embeddedFontBase64Regular = fs2.readFileSync(p).toString("base64");
        break;
      }
    }
  }
} catch (e) {
  console.warn("Could not read font files for base64 embedding:", e);
}
