function getRelatedNoticesForPost(item, allPosts, maxItems = 4) {
  const pool = allPosts.filter(
    (p) => p.id !== item.id && isPublishedSarkariItem(p) && !p.duplicateOfId && !KNOWN_DUPLICATE_MAP[p.id]
  );
  const byId = new Map(pool.map((p) => [p.id, p]));
  const results = [];
  const seen = /* @__PURE__ */ new Set();
  for (const cluster of CURATED_RELATED_CLUSTERS) {
    if (!cluster.ids.includes(item.id)) continue;
    for (const targetId of cluster.ids) {
      if (targetId === item.id || seen.has(targetId)) continue;
      const target = byId.get(targetId);
      if (!target) continue;
      seen.add(targetId);
      results.push({
        id: target.id,
        title: target.title,
        relationLabel: cluster.labels[targetId] || target.advertisementNo || "Related Notice",
        dateText: target.lastDate || target.postDate
      });
    }
  }
  if (results.length < 2) {
    for (const candidate of pool) {
      if (results.length >= Math.min(maxItems, 3)) break;
      if (seen.has(candidate.id)) continue;
      if (candidate.category === item.category) {
        seen.add(candidate.id);
        results.push({
          id: candidate.id,
          title: candidate.title,
          relationLabel: candidate.advertisementNo || "Related Category Notice",
          dateText: candidate.lastDate || candidate.postDate
        });
      }
    }
  }
  return results.slice(0, maxItems);
}
function getDomainFromUrl(rawUrl) {
  try {
    const parsed = new URL(rawUrl);
    return parsed.hostname.replace(/^www\./i, "");
  } catch {
    return rawUrl;
  }
}
function buildPostEnrichmentData(item, effectiveType, statusInfo, orgName, portalUrl) {
  const sourceDomain = getDomainFromUrl(portalUrl);
  const startRaw = item.applyStart || item.startDate;
  const endRaw = item.applyEnd || item.lastDate;
  const startLong = startRaw ? formatLongDate(startRaw) || startRaw : "";
  const endLong = endRaw ? formatLongDate(endRaw) || endRaw : "";
  const postLong = formatLongDate(item.postDate || item.documentDate) || item.postDate || "recent circular";
  const verifiedDateText = formatLongDate(
    item.updatedAt || item.verification?.lastVerified || item.postDate || item.documentDate
  ) || item.postDate || "As per official notice";
  const hasVacancies = hasRealDataValue(item.totalPosts || item.posts) && !isGenericNoticePlaceholder(item.totalPosts || item.posts);
  const vacanciesStr = String(item.totalPosts || item.posts || "").trim();
  const qualStr = hasRealDataValue(item.eligibility || item.qualification) && !isGenericNoticePlaceholder(item.eligibility || item.qualification) ? String(item.eligibility || item.qualification).trim() : "the prescribed criteria in the official notification";
  const genFee = item.fee?.genObc || item.fees?.genObc;
  const scFee = item.fee?.scSt || item.fees?.scSt;
  const hasFee = hasRealDataValue(genFee) || hasRealDataValue(scFee);
  const isEdu = item.section === "education" || item.category === "ignou" || item.category === "admissions" || item.category === "exam_forms" || item.category === "cluster_univ" || item.category === "nta";
  const quickSummary = [];
  const leadText = (item.summary || item.shortInfo || "").trim();
  if (leadText) {
    quickSummary.push(leadText);
  }
  quickSummary.push(
    `Issued by ${orgName}${hasRealDataValue(item.advertisementNo) ? ` (${item.advertisementNo})` : ""}${postLong ? ` and published on ${postLong}` : ""}.`
  );
  if (effectiveType === "result" || effectiveType === "answer_key") {
    quickSummary.push(
      statusInfo.isClosingSoon && endLong ? `Window / objection period runs until ${endLong} via ${sourceDomain}.` : `Official update published on ${sourceDomain}. Review roll numbers, marks, or PDF details directly on the portal.`
    );
  } else if (effectiveType === "admit_card" || effectiveType === "exam" || effectiveType === "dv") {
    quickSummary.push(
      `Current status: ${statusInfo.badgeLabel}${statusInfo.dateValue ? ` (${statusInfo.dateValue})` : ""}. Official details are hosted on ${sourceDomain}.`
    );
  } else {
    quickSummary.push(
      `${hasVacancies ? `Reported count / scope: ${vacanciesStr}. ` : ""}${endLong ? statusInfo.isClosed ? `Submission deadline closed on ${endLong}.` : `Application / form window ${startLong ? `from ${startLong} ` : ""}closes on ${endLong}.` : `Check ${sourceDomain} for exact schedule details.`}`
    );
    if (hasFee) {
      quickSummary.push(
        `Fee noted in notice: ${genFee || "As per notice"}${scFee && scFee !== genFee ? ` (Reserved/SC/ST: ${scFee})` : ""}.`
      );
    }
  }
  const whoShouldApply = [];
  if (effectiveType === "result" || effectiveType === "admit_card" || effectiveType === "dv" || effectiveType === "exam" || effectiveType === "answer_key") {
    whoShouldApply.push(
      `Candidates registered under ${orgName} for ${item.title} (${hasRealDataValue(item.learnerGroup) ? item.learnerGroup : qualStr}).`
    );
    whoShouldApply.push(
      effectiveType === "answer_key" ? `Appeared examinees reviewing ${orgName} responses${statusInfo.isClosingSoon && endLong ? ` before ${endLong}` : ""}.` : effectiveType === "dv" ? `Shortlisted applicants carrying originals required by ${orgName}.` : `Holders of valid ${orgName} roll/registration numbers for ${item.title}.`
    );
    if (item.jkDomicile) {
      whoShouldApply.push(`Eligible J&K domicile residents covered in ${item.title}.`);
    }
  } else {
    whoShouldApply.push(
      `Applicants fulfilling ${qualStr} as notified by ${orgName} in ${item.title}.`
    );
    if (hasRealDataValue(item.ageLimit) && !isGenericNoticePlaceholder(item.ageLimit)) {
      whoShouldApply.push(
        `Candidates within ${orgName} age bounds (${item.ageLimit}) for ${item.title}.`
      );
    }
    if (item.jkDomicile) {
      whoShouldApply.push(`Holders of valid Jammu & Kashmir Domicile Certificates for ${item.title}.`);
    }
    whoShouldApply.push(
      statusInfo.isClosed ? `Window closed (${endLong || statusInfo.dateValue}); kept for reference.` : `Candidates with active contact details ready before ${endLong || "the deadline"} on ${sourceDomain}.`
    );
  }
  const whoShouldNotApply = [];
  if (statusInfo.isClosed || statusInfo.isCancelled) {
    whoShouldNotApply.push(
      statusInfo.isCancelled ? `All applicants \u2014 ${orgName} cancelled ${item.title}.` : `New applicants \u2014 ${item.title} closed on ${endLong || statusInfo.dateValue}.`
    );
  }
  if (effectiveType === "result" || effectiveType === "admit_card" || effectiveType === "dv" || effectiveType === "answer_key" || effectiveType === "exam") {
    whoShouldNotApply.push(
      `Unregistered applicants \u2014 ${item.title} covers existing ${orgName} candidates only.`
    );
  } else {
    whoShouldNotApply.push(
      `Awaited-result candidates beyond ${orgName} cutoff rules unless ${item.title} allows it.`
    );
    if (item.jkDomicile) {
      whoShouldNotApply.push(`Non-domicile applicants where ${orgName} mandates J&K domicile.`);
    }
    if (hasRealDataValue(item.ageLimit) && !isGenericNoticePlaceholder(item.ageLimit)) {
      whoShouldNotApply.push(`Candidates outside ${item.ageLimit} without ${orgName} relaxation.`);
    }
  }
  const commonMistakes = [
    `Skipping the original ${item.title} notice on ${sourceDomain}.`,
    effectiveType === "application" || effectiveType === "admission" || effectiveType === "upcoming" ? `Uploading oversized/unclear scans to ${sourceDomain} instead of verifying KB/pixel specs.` : `Mismatched roll number or DOB entry when checking ${item.title} on ${sourceDomain}.`,
    `Spelling differences versus Class 10th records for ${orgName} verification.`,
    hasFee ? `Double-paying ${item.title} fees before bank settlement checks.` : `Waiting until closing hours on ${sourceDomain} when traffic peaks.`
  ];
  if (item.jkDomicile || !isEdu) {
    commonMistakes.push(
      `Claiming reserved categories without valid certificates dated by ${endLong || "cutoff"}.`
    );
  }
  const whatToDoNext = [
    `1. Confirm ${item.title} (${postLong}) directly on ${sourceDomain}.`,
    statusInfo.isClosed ? `2. Follow post-closing ${orgName} updates (${endLong || "closed"}) on ${sourceDomain}.` : statusInfo.isUpcoming ? `2. Prepare certificates for ${item.title} ahead of ${startLong || "opening"}.` : effectiveType === "result" || effectiveType === "admit_card" || effectiveType === "answer_key" ? `2. Sign in on ${sourceDomain} with registration ID${endLong ? ` before ${endLong}` : ""} for ${item.title}.` : `2. Submit ${item.title} on ${sourceDomain} before ${endLong || "closing"}${startLong ? ` (opened ${startLong})` : ""}.`,
    `3. Save the official ${orgName} PDF or confirmation receipt for ${item.title}.`
  ];
  return {
    quickSummary,
    whoShouldApply,
    whoShouldNotApply,
    commonMistakes,
    whatToDoNext,
    sourceDomain,
    portalUrl,
    verifiedDateText
  };
}

