// src/utils/seoConfig.ts
var SITE_ORIGIN = "https://www.cscdost.com";
function normalizeSeoWhitespace(text) {
  return String(text || "").replace(/\s+/g, " ").replace(/\u2013|\u2014/g, "-").trim();
}
function trimAtWordBoundary(text, maxLen) {
  const clean = normalizeSeoWhitespace(text);
  if (clean.length <= maxLen) return clean;
  const sliced = clean.slice(0, maxLen + 1);
  const lastSpace = sliced.lastIndexOf(" ");
  const cut = lastSpace >= Math.floor(maxLen * 0.55) ? sliced.slice(0, lastSpace) : clean.slice(0, maxLen);
  return cut.replace(/[\s,;:\-–—(\[/]+$/g, "").trim();
}
function compactTitlePhrases(raw) {
  return normalizeSeoWhitespace(raw).replace(/\bJammu\s*(?:&|and)\s*Kashmir\b/gi, "J&K").replace(/\bUniversity of Kashmir\b/gi, "Kashmir Univ").replace(/\bCluster University Srinagar\b/gi, "CUS Srinagar").replace(/\bCluster University\b/gi, "Cluster Univ").replace(/\bRegional Centre\b/gi, "RC").replace(/\bExamination Form\b/gi, "Exam Form").replace(/\bExamination\b/gi, "Exam").replace(/\bNotification\b/gi, "Notice").replace(/\bTentative Date Sheet for\b/gi, "Tentative Datesheet").replace(/\bTentative Date Sheet\b/gi, "Tentative Datesheet").replace(/\bRevised Tentative Date Sheet\b/gi, "Rev Datesheet").replace(/\bDate Sheet\b/gi, "Datesheet").replace(/\bSupplementary\b/gi, "Suppl").replace(/\bAssignment Submission\b/gi, "Assignment").replace(/\bRe-Registration\b/gi, "Re-Reg").replace(/\bRegistration\b/gi, "Reg").replace(/\bRecruitment\b/gi, "Jobs").replace(/\bAdmissions\b/gi, "Adm").replace(/\bAdmission\b/gi, "Adm").replace(/\bSemester\b/gi, "Sem").replace(/\bStenographer\b/gi, "Steno").replace(/\bJunior Hindi Translator\b/gi, "JHT").replace(/\bDistance & Online Education\b/gi, "DDOE").replace(/\bOpen & Distance Learning\b/gi, "ODL").replace(/\bCommon Eligibility Test\b/gi, "CET").replace(/\s*\(\s*Closing Today\s*\)/gi, "").replace(/\s*[-–—]\s*Last Date\s+[0-9]{1,2}\s+[A-Za-z]{3,9}\s+[0-9]{4}/gi, "").replace(/\s+/g, " ").trim();
}
function formatSeoTitle(rawTitle, suffix = " | CSC DOST", maxLen = 59) {
  const clean = normalizeSeoWhitespace(rawTitle);
  if (!clean) return "CSC DOST Portal";
  if (clean.length + suffix.length <= maxLen) {
    return `${clean}${suffix}`;
  }
  const compacted = compactTitlePhrases(clean);
  if (compacted.length + suffix.length <= maxLen) {
    return `${compacted}${suffix}`;
  }
  const budgetWithSuffix = maxLen - suffix.length;
  if (budgetWithSuffix >= 36) {
    const parenMatch = compacted.match(/\(([^()]{2,18})\)$/);
    if (parenMatch) {
      const tag = ` (${parenMatch[1].trim()})`;
      const headBudget = budgetWithSuffix - tag.length;
      if (headBudget >= 22) {
        const head = trimAtWordBoundary(compacted.slice(0, compacted.length - parenMatch[0].length), headBudget);
        return `${head}${tag}${suffix}`.slice(0, maxLen);
      }
    }
    const trimmed = trimAtWordBoundary(compacted, budgetWithSuffix);
    if (trimmed.length >= 24) {
      return `${trimmed}${suffix}`;
    }
  }
  if (compacted.length <= maxLen) return compacted;
  return trimAtWordBoundary(compacted, maxLen);
}
